    import sys
    s = sys.stdin.readline().strip()
    k = int(sys.stdin.readline().strip())
    n = len(s)
    result = s
    for i in range(n + 1):
        for j in range(i, n + 1):
            if j - i <= n and (n - (j - i)) <= (k - 1) * n:
                candidate = s[:i] + s[i:j][::-1] + s[j:]
